    let mut score = 0.0;

    // Favor bins with higher remaining capacity
    score += (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 1.5;

    // Penalize creating bins with too little space left after placing the item
    if post_residual < 5 {
        score -= 2.0;
    } else if post_residual < 10 {
        score -= 1.0;
    }

