    // Penalize creating bins that cannot fit the next item
    if next_item_size != 0 && post_residual < next_item_size {
        score -= 3.0;
    }

    // Reward bins with a higher number of fitting items
    score += (fitting_bins_count as f64).sqrt() * 0.5;

    // Penalize having too many open bins
    if open_bins_count > total_items / 2 {
        score -= 1.0;
    }

    score
}

